#include <iostream>
using namespace std;

int main() {
    for (int i = 1; i <= 5; i++) {
        if (i == 2) {
            continue;   // salta esta vuelta
        }
        if (i == 4) {
            break;      // termina el ciclo
        }
        cout << i << endl;
    }

    int opcion = 2;
    switch (opcion) {
        case 1:
            cout << "Uno" << endl;
            break;
        case 2:
            cout << "Dos" << endl;
            break;
        default:
            cout << "Otro" << endl;
    }

    int n = 0;
    do {
        n++;
    } while (n < 3);

    if (n == 3) {
        cout << "n vale 3" << endl;
    } else {
        cout << "n no vale 3" << endl;
    }
    return 0;
}

explanation:
using y namespace también son reservadas: las usas en using namespace std;
Otras que existen pero no se ven en este curso son class, new, delete, template, try y catch. Aunque no las uses, tampoco sirven como nombres de variables.
Un nombre válido empieza con letra o guion bajo, no lleva espacios ni tildes, y distingue mayúsculas de minúsculas. Por eso int for = 3; no compila, pero int Total y int total son dos variables distintas.

