#include <iostream>
using namespace std;

void ordenar(int datos[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (datos[j] > datos[j + 1]) {
                int temp = datos[j];
                datos[j] = datos[j + 1];
                datos[j + 1] = temp;
            }
        }
    }
}

int main() {
    int numeros[5] = {5, 1, 4, 2, 3};
    ordenar(numeros, 5);

    for (int i = 0; i < 5; i++) {
        cout << numeros[i] << " ";
    }
    cout << endl;
    return 0;
}

